import{_ as h,o as t,c as i,a2 as g}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Luật Bảo vệ Môi trường","description":"","frontmatter":{},"headers":[],"relativePath":"vi/46-环境保护法.md","filePath":"vi/46-环境保护法.md","lastUpdated":1789183869000}'),c={name:"vi/46-环境保护法.md"};function a(o,n,r,u,l,m){return t(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="luat-bao-ve-moi-truong" tabindex="-1">Luật Bảo vệ Môi trường <a class="header-anchor" href="#luat-bao-ve-moi-truong" aria-label="Permalink to &quot;Luật Bảo vệ Môi trường&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>46</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Bảo vệ môi trường, nguồn gốc vũ trụ, cộng sinh sinh thái, phát triển bền vững, phòng chống ô nhiễm</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Bảo vệ Môi trường》 là một trong năm luật pháp hỗ trợ của văn minh cộng sinh neo, nhằm bảo vệ môi trường sinh thái và nguồn gốc vũ trụ của Hengyuanzhou, thiết lập khái niệm quản trị môi trường &quot;tiến hóa cộng sinh, phát triển bền vững&quot;, ngăn chặn sự phá hủy hệ sinh thái vũ trụ do khai thác kiểu cướp đoạt, và bảo vệ nền tảng sinh tồn cho sự tiến bộ chung của mọi tộc.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc bảo vệ nguồn gốc</td><td>Nguồn gốc vũ trụ là nền tảng của mọi sự sống và tiến hóa, phải được bảo vệ ưu tiên, và cấm khai thác phá hủy</td></tr><tr><td>Nguyên tắc cộng sinh sinh thái</td><td>Con người và tự nhiên, mỗi tộc và hệ sinh thái đang trong mối quan hệ cộng sinh, và phá hủy sinh thái chính là phá hủy nền tảng sinh tồn của chính mình</td></tr><tr><td>Nguyên tắc bền vững</td><td>Mọi hoạt động khai thác phải cân nhắc lợi ích của thế hệ hiện tại và thế hệ tương lai, phản đối việc cạn kiệt nguồn lực</td></tr><tr><td>Nguyên tắc phòng ngừa là chính</td><td>Bảo vệ môi trường lấy phòng ngừa làm chính, xây dựng hệ thống đánh giá tác động môi trường, và ngăn chặn sự cố ô nhiễm</td></tr><tr><td>Nguyên tắc trách nhiệm của người gây ô nhiễm</td><td>Chủ thể gây ra ô nhiễm môi trường và phá hủy sinh thái phải chịu trách nhiệm xử lý và bồi thường</td></tr><tr><td>Nguyên tắc tham gia công chúng</td><td>Khuyến khích công chúng tham gia bảo vệ môi trường, đảm bảo quyền được biết thông tin môi trường và quyền tham gia của công chúng</td></tr><tr><td>Nguyên tắc phối hợp liên位面</td><td>Bảo vệ môi trường được thúc đẩy thông qua phối hợp liên位面, xây dựng cơ chế hợp tác quản trị môi trường liên位面</td></tr></tbody></table><h2 id="_2-pham-vi-bao-ve-moi-truong" tabindex="-1">2. Phạm vi bảo vệ môi trường <a class="header-anchor" href="#_2-pham-vi-bao-ve-moi-truong" aria-label="Permalink to &quot;2. Phạm vi bảo vệ môi trường&quot;">​</a></h2><p>Phạm vi môi trường được bảo vệ bởi luật này bao gồm tất cả các hệ sinh thái và yếu tố môi trường bên trong Hengyuanzhou:</p><ol><li><strong>Môi trường khí quyển</strong>: Bao gồm tầng khí quyển của mỗi hành tinh, nồng độ năng lượng và cân bằng thành phần của tầng năng lượng.</li><li><strong>Môi trường nước</strong>: Bao gồm chất lượng và lượng nước của nước mặt, nước ngầm, đại dương, và vùng nước năng lượng giữa các位面.</li><li><strong>Môi trường đất</strong>: Bao gồm chất lượng và độ phì nhiêu của đất liền và mạch khoáng sản nguồn lực tu luyện.</li><li><strong>Đa dạng sinh học</strong>: Bao gồm bảo vệ loài và bảo vệ môi trường sống của tất cả động thực vật, vi sinh vật, và sự sống kỳ lạ.</li><li><strong>Môi trường năng lượng</strong>: Bao gồm nồng độ và cân bằng phân bố của linh khí trời đất, năng lượng nguồn gốc, và mảnh vỡ quy luật.</li><li><strong>Môi trường không gian</strong>: Bao gồm sự ổn định không gian位面, khe nứt không gian, và an toàn môi trường của không gian gấp.</li><li><strong>Môi trường miền ý thức</strong>: Bao gồm độ sạch thông tin của không gian ý thức tập thể và phòng chống ô nhiễm tinh thần.</li></ol><h2 id="_3-he-thong-chinh" tabindex="-1">3. Hệ thống chính <a class="header-anchor" href="#_3-he-thong-chinh" aria-label="Permalink to &quot;3. Hệ thống chính&quot;">​</a></h2><h3 id="_1-he-thong-đanh-gia-tac-đong-moi-truong" tabindex="-1">(1) Hệ thống đánh giá tác động môi trường <a class="header-anchor" href="#_1-he-thong-đanh-gia-tac-đong-moi-truong" aria-label="Permalink to &quot;(1) Hệ thống đánh giá tác động môi trường&quot;">​</a></h3><p>Tất cả các dự án phát triển và xây dựng có thể có tác động đáng kể đến môi trường phải trải qua đánh giá tác động môi trường trước khi khởi công. Nội dung đánh giá bao gồm: tác động của dự án đến các yếu tố môi trường như khí quyển, nước, đất, sinh vật, năng lượng, không gian, v.v., các biện pháp phòng ngừa và giảm thiểu, đánh giá rủi ro môi trường, v.v. Các dự án không vượt qua đánh giá tác động môi trường không được khởi công xây dựng.</p><h3 id="_2-he-thong-giay-phep-thai-bo-va-kiem-soat-tong-luong" tabindex="-1">(2) Hệ thống giấy phép thải bỏ và kiểm soát tổng lượng <a class="header-anchor" href="#_2-he-thong-giay-phep-thai-bo-va-kiem-soat-tong-luong" aria-label="Permalink to &quot;(2) Hệ thống giấy phép thải bỏ và kiểm soát tổng lượng&quot;">​</a></h3><p>Nhà nước thực hiện quản lý giấy phép và kiểm soát tổng lượng đối với việc thải bỏ chất ô nhiễm. Đơn vị thải bỏ ô nhiễm phải取得 giấy phép thải bỏ ô nhiễm, và thải bỏ chất ô nhiễm theo các loại, nồng độ, tổng lượng được quy định trong giấy phép. Nhà nước xác định tổng lượng thải bỏ chất ô nhiễm của mỗi khu vực, mỗi位面 theo khả năng chịu tải môi trường, và phân chia theo cấp độ để thực hiện.</p><h3 id="_3-he-thong-đuong-đo-bao-ve-sinh-thai" tabindex="-1">(3) Hệ thống đường đỏ bảo vệ sinh thái <a class="header-anchor" href="#_3-he-thong-đuong-đo-bao-ve-sinh-thai" aria-label="Permalink to &quot;(3) Hệ thống đường đỏ bảo vệ sinh thái&quot;">​</a></h3><p>Nhà nước quy định đường đỏ bảo vệ sinh thái ở các khu vực có giá trị sinh thái đặc biệt, bao gồm:</p><table tabindex="0"><thead><tr><th>Loại đường đỏ</th><th>Nội dung bảo vệ</th></tr></thead><tbody><tr><td>Khu bảo vệ nguồn gốc</td><td>Khu vực sản xuất cốt lõi của năng lượng nguồn gốc vũ trụ, tất cả các hoạt động khai thác đều bị cấm</td></tr><tr><td>Môi trường sống loài</td><td>Môi trường sống cốt lõi của các loài quý hiếm có nguy cơ tuyệt chủng, phá hủy và can thiệp bị cấm</td></tr><tr><td>Khu vực rào chắn sinh thái</td><td>Hệ sinh thái then chốt duy trì cân bằng sinh thái khu vực, khai thác bị hạn chế</td></tr><tr><td>Địa linh thánh tu luyện</td><td>Khu vực giàu năng lượng có giá trị tu luyện đặc biệt, thực hiện sử dụng có bảo vệ</td></tr><tr><td>Vùng giao giới位面</td><td>Vùng chuyển tiếp sinh thái giữa các位面, khai thác phá hủy không gian bị cấm</td></tr></tbody></table><h3 id="_4-he-thong-giam-sat-va-canh-bao-moi-truong" tabindex="-1">(4) Hệ thống giám sát và cảnh báo môi trường <a class="header-anchor" href="#_4-he-thong-giam-sat-va-canh-bao-moi-truong" aria-label="Permalink to &quot;(4) Hệ thống giám sát và cảnh báo môi trường&quot;">​</a></h3><p>Nhà nước xây dựng mạng lưới giám sát môi trường bao phủ toàn bộ vũ trụ, giám sát thời gian thực tình hình thay đổi của từng yếu tố môi trường. Đối với các sự cố ô nhiễm môi trường nghiêm trọng và phá hủy sinh thái có thể xảy ra, xây dựng cơ chế cảnh báo, phát hành thông tin cảnh báo kịp thời và khởi động phản ứng khẩn cấp.</p><h3 id="_5-he-thong-boi-thuong-sinh-thai" tabindex="-1">(5) Hệ thống bồi thường sinh thái <a class="header-anchor" href="#_5-he-thong-boi-thuong-sinh-thai" aria-label="Permalink to &quot;(5) Hệ thống bồi thường sinh thái&quot;">​</a></h3><p>Các khu vực và nhóm mà việc khai thác bị hạn chế do bảo vệ môi trường có quyền nhận bồi thường sinh thái. Quỹ bồi thường sinh thái được chi từ tích lũy công cộng và thu nhập từ khai thác tài nguyên, và được sử dụng cho phát triển kinh tế của khu vực bồi thường cũng như cải thiện đời sống cư dân.</p><h2 id="_4-quy-đinh-moi-truong-ve-hoat-đong-tu-luyen" tabindex="-1">4. Quy định môi trường về hoạt động tu luyện <a class="header-anchor" href="#_4-quy-đinh-moi-truong-ve-hoat-đong-tu-luyen" aria-label="Permalink to &quot;4. Quy định môi trường về hoạt động tu luyện&quot;">​</a></h2><p>Tác động của hoạt động tu luyện đối với môi trường là lĩnh vực đặc biệt của bảo vệ môi trường Hengyuanzhou, và luật này đặc biệt thiết lập các điều khoản quy định:</p><ol><li><strong>Quy định khai thác năng lượng</strong>: Việc khai thác tài nguyên tu luyện phải đáp ứng nguyên tắc bền vững, và cấm khai thác phá hủy gây cạn kiệt năng lượng. Lượng khai thác không được vượt quá tốc độ phục hồi tự nhiên của năng lượng khu vực.</li><li><strong>Xử lý chất thải tu luyện</strong>: Tàn dư năng lượng, dược phẩm tu luyện thải bỏ, pháp khí hỏng, v.v. phát sinh trong quá trình tu luyện phải được xử lý theo quy định, và cấm vứt bỏ tùy tiện gây ô nhiễm năng lượng.</li><li><strong>Đánh giá môi trường tu luyện cao cấp</strong>: Sự đột phá và đóng quan của người tu luyện cao cấp có thể có tác động đáng kể đến môi trường xung quanh, và phải trải qua đánh giá môi trường trước đó cũng như thực hiện các biện pháp bảo vệ.</li><li><strong>Giấy phép khai thác位面</strong>: Việc khai thác位面 mới phải trải qua đánh giá môi trường và điều tra sinh thái, và chỉ có thể thực hiện sau khi xây dựng kế hoạch bảo vệ sinh thái.</li><li><strong>Bảo vệ môi trường sống sự sống kỳ lạ</strong>: Môi trường sống của sự sống kỳ lạ được đưa vào đường đỏ bảo vệ sinh thái, và cấm khám phá cũng như khai thác không có giấy phép.</li></ol><h2 id="_5-trach-nhiem-phap-ly" tabindex="-1">5. Trách nhiệm pháp lý <a class="header-anchor" href="#_5-trach-nhiem-phap-ly" aria-label="Permalink to &quot;5. Trách nhiệm pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ul><li>Khởi công xây dựng không qua đánh giá tác động môi trường, ra lệnh dừng xây dựng, khôi phục trạng thái ban đầu và phạt tiền.</li><li>Thải bỏ chất ô nhiễm vượt tiêu chuẩn, ra lệnh xử lý trong thời hạn và phạt tiền, trường hợp nghiêm trọng thì ra lệnh đóng cửa kinh doanh.</li><li>Phá hủy đường đỏ bảo vệ sinh thái, ra lệnh khôi phục trạng thái ban đầu và phạt tiền, trường hợp nghiêm trọng thì truy cứu trách nhiệm hình sự.</li><li>Khai thác phá hủy tài nguyên tu luyện, tịch thu thu nhập bất hợp pháp và phạt tiền, thu hồi giấy phép khai thác.</li><li>Gây ra sự cố ô nhiễm môi trường nghiêm trọng, chịu trách nhiệm bồi thường, nếu cấu thành tội phạm thì truy cứu trách nhiệm hình sự.</li><li>Nhân viên giám sát môi trường bất cẩn, lạm dụng quyền hạn,给予 kỷ luật, nếu cấu thành tội phạm thì truy cứu trách nhiệm hình sự.</li></ul><h2 id="_6-tham-gia-cong-chung-va-kien-cao-loi-ich-cong-cong-moi-truong" tabindex="-1">6. Tham gia công chúng và kiện cáo lợi ích công cộng môi trường <a class="header-anchor" href="#_6-tham-gia-cong-chung-va-kien-cao-loi-ich-cong-cong-moi-truong" aria-label="Permalink to &quot;6. Tham gia công chúng và kiện cáo lợi ích công cộng môi trường&quot;">​</a></h2><p>Công chúng có quyền tham gia bảo vệ môi trường, và các kênh cụ thể bao gồm:</p><ol><li>Đưa ra ý kiến và đề xuất đối với dự án đánh giá tác động môi trường.</li><li>Báo cáo và khiếu nại đối với các hành vi ô nhiễm môi trường và phá hủy sinh thái.</li><li>Thành lập tổ chức bảo vệ môi trường theo pháp luật, tham gia giám sát môi trường và các hoạt động lợi ích công cộng.</li><li>Đối với các hành vi ô nhiễm môi trường, phá hủy sinh thái gây hại cho lợi ích công cộng, tổ chức bảo vệ môi trường có thể khởi kiện cáo lợi ích công cộng môi trường tại Tòa án Cộng sinh.</li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Bảo vệ Môi trường》 là sự đảm bảo pháp luật của khái niệm phát triển bền vững của văn minh cộng sinh neo. Bằng cách xây dựng các hệ thống như đánh giá tác động môi trường, đường đỏ bảo vệ sinh thái, kiểm soát tổng lượng, nó tích hợp bảo vệ môi trường vào tất cả các hoạt động khai thác và tu luyện, đảm bảo tính bền vững của nguồn gốc vũ trụ và hệ sinh thái, và bảo vệ nền tảng sinh tồn vĩnh cửu cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>39-住房与环境保障 (Đảm bảo Nhà ở và Môi trường)</li><li>15-能量循环与转化法则 (Quy luật Chu trình và Chuyển hóa Năng lượng)</li><li>53-奇特生命识别标准 (Tiêu chuẩn Nhận diện Sự sống Kỳ lạ)</li></ul>',34)])])}const p=h(c,[["render",a]]);export{e as __pageData,p as default};
